<?php get_header();while(have_posts()):the_post();?><article class="wrap"><header class="article-head"><p class="entry-meta"><?php echo esc_html(get_the_date('j F Y'));?> · <?php echo esc_html(get_the_author());?></p><h1><?php the_title();?></h1><?php the_excerpt();?></header><?php if(has_post_thumbnail()||get_post_meta(get_the_ID(),'_kl_image',true)):?><img class="article-cover" src="<?php echo kl_image(get_the_ID());?>" alt="<?php echo esc_attr(get_the_title());?>"><?php endif;?><div class="article-content"><?php the_content();if(get_post_type()==='kl_project'||get_post_type()==='kl_service'):?><p><a class="text-link" href="<?php echo kl_url('contacts');?>">Обсудить проект <?php kl_arrow();?></a></p><?php endif;?></div></article><?php endwhile;get_footer();?>
